"""Write scorecard_x_source.html for qt-05 from results.json (every number from there), then render it with:
google-chrome --headless --screenshot=findings/qt05-inkling-2-mini/scorecard_x.png --window-size=1200,675 --force-device-scale-factor=2 findings/qt05-inkling-2-mini/scorecard_x_source.html"""
import json, re
D = "findings/qt05-inkling-2-mini"
TEMPLATE = r'''<!doctype html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<!-- qt-05 scorecard · generated by make_scorecard.py from results.json; every number from there · Quick Trial: numbers only -->
<style>
@font-face { font-family:"PlexAr"; src:url("../../assets/fonts/sans-arabic-400.woff2"); font-weight:400; }
@font-face { font-family:"PlexAr"; src:url("../../assets/fonts/sans-arabic-500.woff2"); font-weight:500; }
@font-face { font-family:"PlexAr"; src:url("../../assets/fonts/sans-arabic-600.woff2"); font-weight:600; }
@font-face { font-family:"PlexMono"; src:url("../../assets/fonts/mono-400.woff2"); font-weight:400; }
@font-face { font-family:"PlexMono"; src:url("../../assets/fonts/mono-500.woff2"); font-weight:500; }
:root { --ink:#12161C; --paper:#FAF9F6; --rule:#D8D5CE; --signal:#C42B1F; --dim:#6E7178; --soft:#EFEDE7; }
* { margin:0; padding:0; box-sizing:border-box; }
body { width:1200px; height:675px; background-color:var(--paper); background-image:linear-gradient(rgba(18,22,28,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(18,22,28,.045) 1px,transparent 1px); background-size:24px 24px; background-position:-1px -1px; color:var(--ink); font-family:"PlexAr",sans-serif; padding:32px 56px; position:relative; }
.n { font-family:"PlexMono",monospace; font-variant-numeric:tabular-nums; direction:ltr; unicode-bidi:isolate; }
.head { display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--rule); padding-bottom:12px; }
.head img { width:170px; display:block; }
.strip { font-size:15px; color:var(--dim); }
.strip b { color:var(--ink); font-weight:500; }
h1 { font-size:36px; font-weight:600; line-height:1.3; margin-top:10px; }
h1 .model { color:#EB3B2C; }
.en { font-family:"PlexMono",monospace; font-size:15px; color:var(--dim); direction:ltr; text-align:right; margin-top:2px; }
.claim { margin-top:10px; font-size:17px; border-right:3px solid var(--ink); padding-right:10px; }
table { width:100%; border-collapse:collapse; margin-top:16px; background:var(--paper); }
th { font-size:14px; font-weight:500; color:var(--dim); text-align:right; padding:0 10px 6px; border-bottom:1px solid var(--ink); vertical-align:bottom; line-height:1.3; }
td { font-size:18px; text-align:right; padding:0 10px; height:40px; border-bottom:1px solid var(--rule); }
th.num, td.num { text-align:left; }
tr.main td { background:var(--soft); font-weight:500; }
.note { margin-top:12px; font-size:15px; line-height:1.55; }
.note .dim { color:var(--dim); font-size:14px; }
.chips { margin-top:6px; display:flex; flex-wrap:wrap; gap:6px 18px; direction:rtl; }
.chip { white-space:nowrap; font-size:15px; color:var(--dim); }
.chip.me { color:var(--ink); font-weight:500; }
.foot { position:absolute; bottom:24px; left:56px; right:56px; display:flex; justify-content:flex-end; border-top:1px solid var(--rule); padding-top:8px; color:var(--dim); font-family:"PlexMono",monospace; font-size:15px; }
</style>
</head>
<body>
  <div class="head">
    <div class="strip"><b>تجربة سريعة · استكشافية</b> · استقبال عيادة · <span class="n">42</span> حالة × <span class="n">3</span> محاولات · مسجّلة مسبقًا · <span class="n">llama.cpp IQ4_NL · RTX 4090</span> · <span class="n">Nov 2026</span></div>
    <img src="../../assets/brand/miqyas-lockup-on-light.svg" alt="مقياس">
  </div>

  <h1>هل يقدر <span class="model">Inkling 2 Mini</span> يدير استقبال عيادة؟</h1>
  <p class="en">Quick Trial · exploratory · numbers only, no verdict · lowest effort (none)</p>
  <p class="claim">الناشر لا يذكر دعم العربية لهذا النموذج؛ اختبرناه لأننا وعدنا بذلك، استثناءً مؤرخًا من قاعدتنا في اختيار النماذج.</p>

  <table>
    <tr>
      <th>الإعداد</th>
      <th class="num">محادثات صحيحة<br>كاملة</th>
      <th class="num">صحيحة في<br>المحاولات الثلاث</th>
      <th class="num">طوارئ وصلت لموظف<br>في الوقت المناسب</th>
      <th class="num">طوارئ وصلت لموظف<br>في أي وقت</th>
      <th class="num">شكاوى وأسئلة طبية<br>وصلت لموظف</th>
      <th class="num">ثانية<br>لكل رد</th>
    </tr>
{{ROWS}}
  </table>

  <p class="note">المحوّل ناقص الصيغة الخاصة: <span class="n">{{DIFF}} {{DIFFCI}}</span> نقطة</p>
  <p class="note dim" style="margin-top:14px;color:var(--dim);font-size:14px">الإعداد المشترك عبر المحوّل، الطريقة المتاحة لكل النماذج:</p>
  <div class="chips">{{COMMON}}</div>

  <div class="foot">miqyaslab.com</div>
</body>
</html>
'''
r = json.load(open(f"{D}/results.json", encoding="utf-8"))
P = r["parts"]
pct = lambda x: f"{round(x)}%"
short = lambda m: re.sub(r" \(.*\)", "", m)
rows = [("بلا مساعدة في التاريخ", "base-native", ""), ("التقويم داخل التعليمات", "table-native", ""),
        ("أداة التاريخ · صيغته", "tool-native", "main"), ("أداة التاريخ · المحوّل", "tool-adapter", "")]
tr = "\n".join(f'''    <tr class="{c}"><td>{name}</td>
      <td class="num"><span class="n">{pct(P[k]["success_pct"])}</span></td><td class="num"><span class="n">{pct(P[k]["pass3_pct"])}</span></td>
      <td class="num"><span class="n">{P[k]["emergencies_in_time"]}</span></td><td class="num"><span class="n">{"/".join(map(str, P[k]["emergencies_handed_over_at_any_point"]))}</span></td>
      <td class="num"><span class="n">{"/".join(map(str, P[k]["complaint_medical_handed_over"]))}</span></td><td class="num"><span class="n">{P[k]["wait_median_s"]}</span></td></tr>''' for name, k, c in rows)
common = "".join(f'<span class="chip{" me" if m["model"].startswith("Inkling") else ""}"><span class="n">{short(m["model"])} {pct(m["prompted_json_adapter"]["success_pct"])}</span></span>' for m in r["common_setup_two_paths"])
d = r["tool_adapter_minus_own_format"]
html = TEMPLATE
html = html.replace("{{ROWS}}", tr).replace("{{COMMON}}", common).replace("{{DIFF}}", f'{d["points"]:+.1f}'.replace("-", "−")) \
           .replace("{{DIFFCI}}", f'[{d["ci95_points"][0]:+.1f}, {d["ci95_points"][1]:+.1f}]'.replace("-", "−"))
open(f"{D}/scorecard_x_source.html", "w", encoding="utf-8").write(html)
print("written")
